color_extra_css:
:root {
	--primary-light: #FDE7EE;
	--secondary: #F2B56B;
	--text-muted: #8A6B5C;
	--border: #F1E2D6;
	--surface: #FFFFFF;
	--white: #FFFFFF;
	--danger: #D7263D;
	--radius: 18px;
	--radius-lg: 24px;
	--radius-pill: 999px;
	--shadow: 0 10px 30px rgba(59, 36, 24, 0.08);
	--shadow-nav: 0 -6px 24px rgba(59, 36, 24, 0.10);
	--container: 1240px;
	--transition: 260ms cubic-bezier(.22,1,.36,1);
	--font: 'Nunito', system-ui, -apple-system, sans-serif;
	--sn-blue: var(--primary);
	--sn-blue-dark: var(--primary-hover);
	--sm-primary: var(--primary);
	--sm-primary-dark: var(--primary-hover);
	--sm-primary-soft: var(--primary-light);
	--sm-accent: var(--primary);
	--sm-accent-dark: var(--primary-hover);
	--sm-bg: var(--background);
	--sm-surface: var(--surface);
	--sm-text: var(--text);
	--sm-muted: var(--text-muted);
	--sm-border: var(--border);
	--sm-radius: var(--radius);
	--sm-radius-lg: var(--radius-lg);
	--sm-shadow: var(--shadow);
	--sm-shadow-nav: var(--shadow-nav);
}
body.sm-body {
	background-color: var(--background);
	color: var(--text);
	font-family: var(--font);
}
